import json
from pathlib import Path
R=Path(__file__).resolve().parent;s=json.loads((R/'summary.json').read_text())
lines=['# 9-9 受控Chat实际采集与原生路由重放','','状态：本项完成，9-9整体仍为partial。RTX PRO 6000上两个SGLang0.5.13.post1 Qwen3-8B BF16实例，原生Router0.3.2。固定四轮读书会规划问题，模型实际回答进入下一轮上下文；这是实验构造的Chat，不是生产日志或用户行为样本。','','## 输入与设计','','conversation.json保存四问题和简短回答要求。实际使用tokenizer聊天模板、thinking关闭、temperature=0、最多96输出token、允许自然EOS；捕获原始回答、完整消息、输入token、起止时间。三种路由各两轮重放同一份四轮输入，每组清缓存并重启Router，健康注册后发请求。策略顺序seed912轮内打乱，共4次采集加24次重放。重放答案不写回后续输入，避免不同策略输入随答案分叉。','','## 结果','','| 轮次 | 策略 | 实例序列 | 请求命中率 | token加权命中率 | 请求完成中位秒 | 与采集回答相同 |','|---:|---|---|---:|---:|---:|---:|']
for r in s['groups']:lines.append(f"| {r['trial']} | {r['policy']} | {r['worker_sequence']} | {r['request_hit_rate']:.1%} | {r['token_hit_rate']:.3%} | {r['median_s']:.6f} | {r['matches_capture']}/4 |")
lines+=['','![缓存命中](cache-hits.png)','','原始采集回答：','']
for r in s['capture']:lines.append(f"- 第{r['prompt_id']+1}轮，输入{r['prompt_tokens']}token：{r['text'].strip()}")
lines+=['','24次重放逐轮与采集回答一致，全部28响应自然stop且无长度截断。人工按题面核对：前两轮正确；第三轮应为35分钟而回答30分钟，第四轮沿用30分钟错误（细节见quality-review.json）。因此输出一致不等于正确，第四轮输入也已经包含上一轮错误。缓存亲和两轮token命中64.940%，轮转和本次power_of_two为36.653%，但完成时间中位接近，不能称质量或整体性能提升。完整原文见summary.json及results/capture.jsonl。对照必须检查自然结束/长度截断字段，不能仅以响应成功推断任务完成。输入来自实际生成对话，但四轮短规划任务不能代表Chat总体质量。','','命中层级为本worker的显存KV；无远端缓存，远端取回及其p95不适用。summary.json逐请求给出前次同worker完成到当前发送的间隔；首次访问为null。采集轮间间隔也保存。它们包括客户端模板构造、记录与立即续发开销，不代表人类思考或工具执行时间。不同worker的间隔不是全局复用间隔，也不是网络取回时间。串行轻载、每策略每轮仅四请求，不报稳定尾延迟或吞吐胜负。','','## 重现与证据','','run.py保留完整worker/Router命令和绝对权重路径，专用环境同上级实验。确认31090/31091/31092/31099空闲，在不存在results的独立副本中用专用SGLang环境Python执行run.py。已有results拒绝覆盖。CUDA13工具链和9-8实际JIT缓存路径固定；disable-cuda-graph不意味着关闭全部piecewise prefill图。只终止自建进程组，清理退出码记录于execution.json。','','离线 `python3 analyze.py` 核验执行源码哈希、完整多轮消息链、注册健康、原生worker接收/完成日志、输入长度、输出与停止原因，生成summary.json。`python plot.py`需要Matplotlib，`python3 write_report.py`重建本报告。results保留每轮真实采集和24个请求响应、原生日志与metrics；manifest.json封存文件SHA，cleanup-check.json与gpu-after.txt保留退出和原有服务证据。','','没有调用calculations；自然容量淘汰、重启和远端比较等仍待，最终跨session实验与论文复核尚未开始。','']
(R/'README.md').write_text('\n'.join(lines))
